import React, { useState } from 'react';
import Sidebar from './Sidebar';
import { useAuth } from '../App';

export default function DashboardLayout({ children, title, subtitle }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notifOpen, setNotifOpen]     = useState(false);
  const { user } = useAuth();

  const alerts = [
    { icon: '⚠️', text: 'Heavy rain expected Thursday', time: '2h ago', color: 'text-amber-600' },
    { icon: '🔬', text: 'Rust risk detected in your zone', time: '5h ago', color: 'text-red-600' },
    { icon: '💰', text: 'Wheat MSP increased to ₹2,275', time: '1d ago', color: 'text-brand-700' },
  ];

  return (
    <div className="page-bg flex">
      <Sidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} />

      <div className="flex-1 lg:ml-60 flex flex-col min-h-screen">
        {/* Topbar */}
        <header className="topbar sticky top-0 z-20 px-6 py-3 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button
              onClick={() => setSidebarOpen(true)}
              className="lg:hidden text-slate-500 hover:text-slate-800 text-xl"
            >☰</button>
            <div>
              <h1 className="font-display font-bold text-slate-800 text-lg leading-tight">{title}</h1>
              {subtitle && <p className="text-slate-400 text-xs mt-0.5">{subtitle}</p>}
            </div>
          </div>

          <div className="flex items-center gap-3">
            {user?.gps && (
              <div className="hidden sm:flex items-center gap-1.5 badge badge-green">
                <span className="text-xs">📍</span>
                <span>{user.gps.lat}, {user.gps.lng}</span>
              </div>
            )}

            {/* Notifications */}
            <div className="relative">
              <button
                onClick={() => setNotifOpen(n => !n)}
                className="relative w-9 h-9 rounded-lg border border-slate-200 bg-white flex items-center justify-center text-slate-500 hover:bg-slate-50 transition-colors"
              >
                🔔
                <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full text-white text-xs flex items-center justify-center font-bold">3</span>
              </button>

              {notifOpen && (
                <div className="absolute right-0 top-11 w-72 notif-dropdown z-50 overflow-hidden animate-fade-in">
                  <div className="px-4 py-3 border-b border-slate-100">
                    <span className="font-semibold text-slate-800 text-sm">Notifications</span>
                  </div>
                  {alerts.map((a, i) => (
                    <div key={i} className="px-4 py-3 hover:bg-slate-50 transition-colors flex items-start gap-3 border-b border-slate-50 last:border-0">
                      <span className="text-lg flex-shrink-0">{a.icon}</span>
                      <div className="flex-1">
                        <div className={`text-xs font-medium ${a.color}`}>{a.text}</div>
                        <div className="text-slate-400 text-xs mt-0.5">{a.time}</div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* AI status */}
            <div className="hidden sm:flex items-center gap-1.5 badge badge-green">
              <span className="w-1.5 h-1.5 rounded-full bg-brand-500 animate-pulse" />
              AI Active
            </div>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 p-5 overflow-auto" onClick={() => setNotifOpen(false)}>
          {children}
        </main>
      </div>
    </div>
  );
}
